using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class AuditLioraShading {
 public static object Run(){Directory.CreateDirectory("Data/Liora/ShadingRepair");var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Sandbox/Characters/Liora/Candidate/Liora_Candidate.prefab");var face=prefab.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Face");var all=UnityEngine.Object.FindObjectsByType<SkinnedMeshRenderer>(FindObjectsInactive.Include,FindObjectsSortMode.None).Where(r=>r.gameObject.scene.IsValid()&&r.transform.root.name.Contains("Liora"));
 var sections=JObject.Parse(File.ReadAllText("Data/Liora/HierarchyRepair/sections.json"))["sections"];
 var report=new{playing=EditorApplication.isPlaying,prefab=AssetDatabase.GetAssetPath(prefab),mesh=AssetDatabase.GetAssetPath(face.sharedMesh),vertices=face.sharedMesh.vertexCount,shapes=face.sharedMesh.blendShapeCount,sections,materials=face.sharedMaterials.Select(m=>new{m.name,shader=m.shader.name,textures=m.GetTexturePropertyNames().Select(p=>new{slot=p,path=AssetDatabase.GetAssetPath(m.GetTexture(p)),type=(AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(m.GetTexture(p))) as TextureImporter)?.textureType.ToString()}),bumpScale=m.HasProperty("_BumpScale")?m.GetFloat("_BumpScale"):0}),live=all.Select(r=>new{r.name,root=r.transform.root.name,active=r.gameObject.activeInHierarchy,mesh=AssetDatabase.GetAssetPath(r.sharedMesh),materials=r.sharedMaterials.Select(AssetDatabase.GetAssetPath)}),scenes=Enumerable.Range(0,SceneManager.sceneCount).Select(j=>SceneManager.GetSceneAt(j)).Select(s=>new{s.path,s.isDirty})};
 File.WriteAllText("Data/Liora/ShadingRepair/audit.json",JsonConvert.SerializeObject(report,Formatting.Indented));return new{report.playing,report.mesh,report.vertices,report.shapes,live=report.live};}
}
